	private void writeFingerprint(DataOutputStream out) throws IOException {
		out.writeUTF(System.getProperty("os.arch", ""));
		out.writeUTF(System.getProperty("java.vendor", "") + '/' + System.getProperty("java.version", ""));
		out.writeInt(FEATURE_MODEL_VERSION);
		out.writeInt(LmdbNativeCostVector.Feature.values().length);
		LmdbNativeCostModelContext context = store.context();
		out.writeLong(context == null ? 0L : context.storeUuid().getMostSignificantBits());
		out.writeLong(context == null ? 0L : context.storeUuid().getLeastSignificantBits());
		out.writeLong(context == null ? 0L : context.indexGeneration().getAsLong());
	}

	private boolean readFingerprintMatches(DataInputStream in) throws IOException {
		ByteArrayOutputStream expected = new ByteArrayOutputStream();
		try (DataOutputStream out = new DataOutputStream(expected)) {
			writeFingerprint(out);
		}
		byte[] expectedBytes = expected.toByteArray();
		byte[] actual = new byte[expectedBytes.length];
		in.readFully(actual);
		return java.util.Arrays.equals(expectedBytes, actual);
	}

	private static LmdbNativePosteriorNode decay(LmdbNativePosteriorNode node, double staleness,
			double priorVariance, LmdbNativePosteriorConfig config, long nowMillis) {
		double tauSaved = 1.0 / node.epistemicVariance;
		double tauLoaded = Math.min(config.persistPrecisionCap(), staleness * tauSaved);
		double variance = tauLoaded > 0.0 ? Math.max(config.varianceFloorGlobal(), 1.0 / tauLoaded) : priorVariance;
		variance = Math.min(variance, priorVariance); // never load MORE certain than a fresh prior... of that level
		return new LmdbNativePosteriorNode(node.meanLog, variance,
				Math.max(config.noiseFloorLog(), node.noiseVariance), node.weightSum * staleness,
				node.squaredWeightSum * staleness, node.completedCount, node.censoredCount, 0L, nowMillis);
	}

	private static void writeRegime(DataOutputStream out, LmdbNativeRegimeKey regime) throws IOException {
		out.writeByte(regime.phase().ordinal());
		out.writeLong(regime.adjacencyEpoch());
		out.writeBoolean(regime.kernelReady());
		out.writeLong(regime.dataGeneration());
	}

	private static LmdbNativeRegimeKey readRegime(DataInputStream in) throws IOException {
		return new LmdbNativeRegimeKey(LmdbNativeRegimeKey.Phase.values()[in.readByte()], in.readLong(),
				in.readBoolean(), in.readLong());
	}

	private static LmdbNativeCostPosteriorStore.Lane readLane(DataInputStream in) throws IOException {
		return LmdbNativeCostPosteriorStore.Lane.values()[in.readByte()];
	}

	private static void writeFamilyShape(DataOutputStream out, LmdbNativeFamilyShapeKey shape) throws IOException {
		out.writeUTF(shape.strategyFamily());
		out.writeByte(shape.executionMode().ordinal());
		out.writeInt(shape.boundMaskClass());
	}

